3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
9	
10	/**
11	 * Rejects a create when another owner shares this owner's last name and address
12	 * (compared case-insensitively with collapsed whitespace), unless the request opted in
13	 * with {@code sharesHousehold}.
14	 */
15	public class EnsureOwnerHouseholdUnique {
16	
17	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
18	            throws DuplicateHouseholdException {
19	        if (Boolean.TRUE.equals(sharesHousehold)) {
20	            return;
21	        }
22	        String lastName = key(owner.getLastName());
23	        String address = key(owner.getAddress());
24	        boolean clash = ownerRepository.findAll().stream()
25	                .anyMatch(other -> key(other.getLastName()).equals(lastName)
26	                        && key(other.getAddress()).equals(address));
27	        if (clash) {
28	            throw new DuplicateHouseholdException(
29	                    "An owner with the same last name and address already exists");
30	        }
31	    }
32	
33	    private static String key(String value) {
34	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
35	    }
36	}
