6	/**
7	 * Counts the owners that belong to {@code owner}'s household, i.e. those resolving to the
8	 * same {@link HouseholdId}. Includes {@code owner} itself, so the value is the household's
9	 * total membership at read time.
10	 */
11	public final class Household {
12	
13	    private Household() {
14	    }
15	
16	    public static int size(Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = HouseholdId.of(owner);
18	        return (int) ownerRepository.findAll().stream()
19	                .filter(other -> HouseholdId.of(other).equals(householdId))
20	                .count();
21	    }
22	}
