2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives the stable identifier shared by every owner in the same household. A household
12	 * is the set of owners with the same last name at the same address (compared
13	 * case-insensitively with collapsed whitespace, matching {@link EnsureOwnerHouseholdUnique}),
14	 * so joiners created with {@code sharesHousehold} always resolve to the same value.
15	 */
16	public final class HouseholdId {
17	
18	    private HouseholdId() {
19	    }
20	
21	    public static String of(Owner owner) {
22	        String seed = key(owner.getLastName()) + "\n" + key(owner.getAddress());
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256")
25	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(16);
27	            for (int i = 0; i < 8; i++) {
28	                sb.append(String.format("%02X", digest[i]));
29	            }
30	            return sb.toString();
31	        }
32	        catch (NoSuchAlgorithmException e) {
33	            throw new IllegalStateException(e);
34	        }
35	    }
36	
37	    private static String key(String value) {
38	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
40	}
