package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import tools.jackson.databind.node.ObjectNode;

/** identity-key: duplicate detection is one derived 'identityKey' = normalizedTelephone|email|householdId. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreRejectsIdentityCollision() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		createOwner(a.deepCopy()).andExpect(status().isConflict()); // same whole identityKey
	}

	@Test
	void sameHouseholdDifferentTelephoneAllowed() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		ObjectNode b = a.deepCopy();
		b.put("telephone", uniqueTelephone()); // same household, different telephone => different identityKey
		createOwnerOk(b);
	}
}

